const items = $input.all();
const failed = items.filter(i => (i.json.statusCode || 200) >= 400);
const ok = items.filter(i => (i.json.statusCode || 200) < 400);

const deployUrl = $('Vercel Deploy Webhook').item.json.body?.deployment?.url || 'albanexa.com';
const duration = Date.now() - new Date($('Vercel Deploy Webhook').item.json.body?.createdAt || Date.now()).getTime();

let status = failed.length === 0 ? '✅' : '❌';
let report = `${status} *Albanexa Deploy QA*\n`;
report += `🚀 ${deployUrl}\n`;
report += `📊 ${ok.length}/${items.length} sayfa OK\n\n`;

if (failed.length > 0) {
  report += `*Başarısız:*\n`;
  failed.forEach(i => { report += `• ${i.json.url} → ${i.json.statusCode}\n`; });
} else {
  report += `*Tüm kritik sayfalar erişilebilir.*`;
}

return [{ json: { report, failed: failed.length } }];
